const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get cart for user
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = 'user_03dd1ad7'\").get();
if (!cart) { console.log('No cart found'); process.exit(); }
console.log('=== CART ===');
for (const [k,v] of Object.entries(cart)) {
  if (k.endsWith('_json') && v) {
    console.log(k + ':', JSON.stringify(JSON.parse(v), null, 2));
  } else {
    console.log(k + ':', v);
  }
}

// Get cart items
const items = db.prepare(\"SELECT ci.*, p.name, p.price, p.category FROM cart_items ci LEFT JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?\").all(cart.cart_id);
console.log('\n=== CART ITEMS ===');
for (const item of items) {
  console.log(JSON.stringify(item, null, 2));
}

// Get the promo
const promo = db.prepare(\"SELECT * FROM promotions WHERE promo_code = 'SAVE20OFF'\").get();
console.log('\n=== PROMO ===');
for (const [k,v] of Object.entries(promo)) {
  if (k.endsWith('_json') && v) {
    console.log(k + ':', JSON.stringify(JSON.parse(v), null, 2));
  } else {
    console.log(k + ':', v);
  }
}
"

