const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Apply SAVE20OFF: \$20 fixed discount
const newDiscount = 20;
const newTotal = 102 - newDiscount;
const newPromos = JSON.stringify(['SAVE20OFF']);

db.prepare(\`
  UPDATE carts 
  SET discount_amount = ?, 
      total = ?, 
      applied_promo_codes_json = ?
  WHERE cart_id = 'CART-user_03dd1ad7'
\`).run(newDiscount, newTotal, newPromos);

// Verify the update
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_03dd1ad7'\").get();
for (const [k,v] of Object.entries(cart)) {
  if (k.endsWith('_json') && v) {
    console.log(k + ':', JSON.stringify(JSON.parse(v), null, 2));
  } else {
    console.log(k + ':', v);
  }
}
"
